---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Score breakdown: A score out of 100 whose gauge is split by what goes into it, with the weakest part flagged and a fix to try.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change score-breakdown.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './score-breakdown.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="score-breakdown" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="sbx panel">
  <div class="sbx-top">
    <div class="sbx-g" role="meter" aria-label="Quality score" aria-valuemin="0" aria-valuemax="100"><svg viewBox="0 0 200 108" aria-hidden="true"></svg><div class="sbx-v"><b class="num">0</b><span class="muted">of 100</span></div></div>
    <div class="sbx-s"><b>Support agent quality</b><span class="sbx-band"><span class="muted sbx-bw">Scoring</span><span class="tag ok num sbx-ch" hidden></span></span></div>
  </div>
  <div class="sbx-list"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './score-breakdown.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Score breakdown ---------- */
/* the gauge is split into one segment per factor, sized by its weight, each filled by the points it earned; the rows under it
   say what each earned and why, and the weakest one says so in words */
.sbx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.sbx-top{display:flex;align-items:center;gap:var(--dm-s-4)}
.sbx-g{position:relative;width:160px;height:88px;flex:none}
.sbx-g svg{width:100%;height:100%;overflow:visible}
.sbx-g path{fill:none;stroke-width:16;stroke-linecap:butt;transition:opacity .3s}
.sbx-g .tr{stroke:var(--dm-chip)}
.sbx-g.hov g:not(.on) .fl{opacity:.3}
.sbx-g g{cursor:default}
.sbx-v{position:absolute;left:0;right:0;bottom:0;display:flex;flex-direction:column;align-items:center;line-height:1.25}
.sbx-v b{font-size:14px;font-weight:500}
.sbx-v .muted{font-size:11px}
.sbx-s{display:flex;flex-direction:column;gap:2px;font-size:13.5px;min-width:0}
.sbx-s b{font-weight:500}
.sbx-band{display:flex;align-items:baseline;gap:var(--dm-s-2);flex-wrap:wrap;font-size:12.5px}
/* the change chip keeps its centred text when it crossfades (a swapped element is otherwise an inline block, which drops
   its text to the top), and shares a baseline with the band word beside it */
.sbx-band .tag{display:inline-flex}
.sbx-list{display:flex;flex-direction:column;gap:2px;padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.sbx-r{border-radius:calc(10px * var(--dm-rk));transition:background .2s}
.sbx-r.on,.sbx-r.open{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.sbx-r:hover{background:var(--dm-row)}}
.sbx-rh{display:grid;grid-template-columns:8px minmax(0,1fr) auto 56px 12px;align-items:center;column-gap:10px;width:100%;padding:var(--dm-s-2);font-size:13px;text-align:left}
.sbx-rh>i{width:8px;height:8px;border-radius:calc(2px * var(--dm-rk))}
.sbx-rh .n{display:flex;align-items:baseline;gap:6px;min-width:0}
.sbx-rh .n>span:first-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sbx-rh .tag{display:inline-flex;align-items:center;height:18px;padding-block:0;font-size:11px;line-height:1;flex:none;align-self:center}
.sbx-rh:focus-visible{outline-offset:-2px;border-radius:inherit}
.sbx-rh .e{font-size:12px;color:var(--dm-fg2)}
.sbx-rh .bar{height:5px;border-radius:calc(3px * var(--dm-rk));background:var(--dm-line);overflow:hidden}
.sbx-rh .bar i{display:block;height:100%;width:0;border-radius:inherit;transition:width .8s var(--dm-ease)}
.sbx-rh>svg{color:var(--dm-muted);transition:transform .35s var(--dm-ease)}
.sbx-r.open .sbx-rh>svg{transform:rotate(90deg)}
.sbx-nt{grid-column:2/-1;font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media (hover:hover) and (pointer:fine){.sbx-r:is(:hover,.on,.open) .sbx-nt{color:var(--dm-fg2)}}
.sbx-d{padding:0 var(--dm-s-2) 10px calc(var(--dm-s-2) + 18px);display:flex;flex-direction:column;gap:var(--dm-s-2);font-size:12.5px;color:var(--dm-fg2);line-height:1.5}
.sbx-d .acts{display:flex;gap:6px;flex-wrap:wrap}
.sbx-pr{display:flex;flex-direction:column;gap:6px;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.sbx-pr .k{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--dm-muted)}
.sbx-pr .k .i{color:var(--dm-accent-fg,var(--dm-accent))}
.sbx-pr .gain{font-size:12px;color:var(--dm-fg2)}
.sbx-pr .gain b{font-weight:500;color:var(--dm-ok)}
/* on a phone the gauge sits over its title, and the rows drop their small bars */
.sbx{container-type:inline-size}
@container (max-width:340px){.sbx-top{flex-direction:column;gap:var(--dm-s-2)}.sbx-s{align-items:center;text-align:center}.sbx-band{justify-content:center}.sbx-rh{grid-template-columns:8px minmax(0,1fr) auto 12px}.sbx-rh .bar{display:none}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, swap, tween } from '../core/core.js';
DM.def('score-breakdown', (r, c) => {
  // the factors, their weight (the points each can earn), the points earned, the agent's one-line note, and what it would change
  const F = [
    { n:'Accuracy', w:40, e:34, c:'var(--dm-c1)', note:'2 wrong refund amounts in 120 tickets' },
    { n:'Speed', w:20, e:11, c:'var(--dm-c2)', note:'Median reply 6.4s, target under 4s', fix:{ t:'Cache the search results between steps and run the two account lookups at once.', to:17, gain:'About 2.1s faster a reply', after:'Median reply 4.3s, close to the target' } },
    { n:'Cost', w:20, e:16, c:'var(--dm-c3)', note:'$0.11 a ticket, budget $0.12' },
    { n:'Safety', w:20, e:19, c:'var(--dm-c4)', note:'No policy breaks, 1 tone flag' }
  ];
  const LAST = 77;
  const g = $('.sbx-g', r), svg = $('svg', g), vb = $('.sbx-v b', r), bw = $('.sbx-bw', r), ch = $('.sbx-ch', r), list = $('.sbx-list', r);
  const total = () => F.reduce((t, f) => t + f.e, 0), band = s => s >= 90 ? 'Excellent' : s >= 75 ? 'Good' : s >= 60 ? 'Fair' : 'Needs work';
  const weakest = () => F.reduce((m, f, i) => f.e / f.w < F[m].e / F[m].w ? i : m, 0);
  // the gauge: a half circle split by weight, with a small gap between the segments
  const CX = 100, CY = 100, RAD = 86, GAP = .04;
  const at = a => [CX + Math.cos(a) * RAD, CY + Math.sin(a) * RAD];
  const arc = (a0, a1) => { const [x0, y0] = at(a0), [x1, y1] = at(a1); return `M${x0.toFixed(2)} ${y0.toFixed(2)}A${RAD} ${RAD} 0 0 1 ${x1.toFixed(2)} ${y1.toFixed(2)}`; };
  let a = Math.PI; const SEG = F.map(f => { const span = f.w / 100 * Math.PI, s = [a + GAP / 2, a + span - GAP / 2]; a += span; return s; });
  svg.innerHTML = F.map((f, i) => `<g data-i="${i}"><path class="tr" d="${arc(...SEG[i])}"/><path class="fl" style="stroke:${f.c}" d=""/></g>`).join('');
  const G = $$('g', svg);
  const fill = (i, p) => { const [a0, a1] = SEG[i]; $('.fl', G[i]).setAttribute('d', p > 0 ? arc(a0, a0 + (a1 - a0) * Math.min(1, p)) : ''); };
  list.innerHTML = F.map((f, i) => `<div class="sbx-r" data-i="${i}"><button class="sbx-rh" aria-expanded="false"><i style="background:${f.c}"></i><span class="n"><span>${f.n}</span></span><span class="e num"></span><span class="bar"><i style="background:${f.c}"></i></span>${I('chev-r','xs')}<span class="sbx-nt">${f.note}</span></button><div class="fold shut"><div><div class="sbx-d"></div></div></div></div>`).join('');
  const R = $$('.sbx-r', list);
  let score = 0, shownFill = F.map(() => 0);
  function paint(ms = 700){
    const s = total(), w = weakest();
    tween(score, s, ms, x => { vb.textContent = Math.round(x); }); score = s;
    g.setAttribute('aria-valuenow', s); g.setAttribute('aria-valuetext', `${s} of 100, ${band(s).toLowerCase()}, ${s - LAST >= 0 ? 'up' : 'down'} ${Math.abs(s - LAST)} since last week`);
    swap(bw, band(s)); ch.hidden = false; ch.className = 'tag num sbx-ch ' + (s >= LAST ? 'ok' : 'bad'); swap(ch, `${s >= LAST ? '+' : '−'}${Math.abs(s - LAST)} since last week`);
    F.forEach((f, i) => { const row = R[i], from = shownFill[i], to = f.e / f.w; shownFill[i] = to; tween(from, to, ms + i * 120, p => fill(i, p));
      $('.e', row).textContent = `${f.e}/${f.w}`; $('.bar i', row).style.width = to * 100 + '%'; $('.sbx-nt', row).textContent = f.note;
      // the weakest factor is flagged in words
      const n = $('.n', row), tag = $('.tag', n); if (i === w && !tag) n.insertAdjacentHTML('beforeend', '<span class="tag warn">Weakest</span>'); if (i !== w && tag) tag.remove();
      $('.sbx-rh', row).setAttribute('aria-label', `${f.n}: ${f.e} of ${f.w} points${i === w ? ', weakest' : ''}. ${f.note}`); detail(i); });
  }
  // an open row: the note, and for the factor that can improve, Improve, which asks the agent for a proposal
  function detail(i){ const f = F[i], d = $('.sbx-d', R[i]); if (d.dataset.st === 'busy' || d.dataset.st === 'prop') return;
    const lost = f.w - f.e;
    d.innerHTML = `<span>${f.done ? f.done + ' ' : ''}${lost ? `Loses ${lost} of its ${f.w} points` : 'Full marks'}${i === weakest() && lost ? ', the most of any factor for its weight.' : '.'}</span>${f.fix ? `<span class="acts"><button class="pill soft sm sbx-imp">${I('wand','xs')}Improve</button></span>` : ''}`;
    const b = $('.sbx-imp', d); if (b) b.onclick = () => improve(i); }
  const improve = i => c.run(async () => { const f = F[i], d = $('.sbx-d', R[i]); d.dataset.st = 'busy';
    d.innerHTML = `<div class="sbx-pr"><span class="k">${I('spark','xs')}<span class="shim">Looking at 120 slow replies</span></span></div>`; enter(d.firstElementChild);
    await c.wait(1300);
    d.dataset.st = 'prop';
    d.innerHTML = `<div class="sbx-pr"><span class="k">${I('spark','xs')}Proposal</span><span>${f.fix.t}</span><span class="gain">${f.fix.gain}: ${f.n} <b class="num">${f.e} → ${f.fix.to}</b></span><span class="acts"><button class="pill primary sm sbx-ok">Apply</button><button class="pill ghost sm sbx-no">Not now</button></span></div>`;
    $('.sbx-ok', d).onclick = () => { f.e = f.fix.to; f.note = f.fix.after; f.done = 'Applied: search results are cached and the lookups run together.'; delete f.fix; d.dataset.st = ''; paint(900); };
    $('.sbx-no', d).onclick = () => { d.dataset.st = ''; detail(i); $('.sbx-imp', d) && $('.sbx-imp', d).focus({ preventScroll:true }); };
  });
  const open = (i, o) => { const row = R[i]; o = o ?? !row.classList.contains('open'); row.classList.toggle('open', o); $('.fold', row).classList.toggle('shut', !o); $('.sbx-rh', row).setAttribute('aria-expanded', o); };
  // a row and its segment light together, from either side
  const hl = i => { g.classList.toggle('hov', i >= 0); G.forEach((x, j) => x.classList.toggle('on', j === i)); R.forEach((x, j) => x.classList.toggle('on', j === i)); };
  R.forEach((row, i) => { $('.sbx-rh', row).onclick = () => open(i); c.on(row, 'pointerenter', e => { if (e.pointerType !== 'touch') hl(i); }); c.on(row, 'focusin', () => hl(i)); });
  G.forEach((x, i) => { c.on(x, 'pointerenter', e => { if (e.pointerType !== 'touch') hl(i); }); c.on(x, 'pointerleave', () => hl(-1)); });
  c.on(list, 'pointerleave', () => { if (!list.contains(document.activeElement)) hl(-1); });
  c.on(list, 'focusout', e => { if (!list.contains(e.relatedTarget)) hl(-1); });
  vb.textContent = '0';
  c.later(280, () => paint(1000));
  // the preview's story: the weakest factor opens, the agent proposes a fix, the person applies it and the score rises
  if (r === c.st) c.story(async s => {
    await s.beat(5);
    await s.tap($('.sbx-rh', R[1])); await s.beat(3);
    await s.tap($('.sbx-imp', R[1])); s.away();
    await s.until(() => $('.sbx-ok', R[1])); await s.beat(4);
    await s.tap($('.sbx-ok', R[1])); s.away(); await s.beat(6);
  });
});
